package algorithms.math;
import java.util.*;
import java.util.function.*;
import java.math.*;

public class Matrix {
public static double[][] identity(int n){double[][] o=new double[n][n];for(int i=0;i<n;i++)o[i][i]=1;return o;}public static double[][] multiply(double[][] a,double[][] b){int r=a.length,k=b.length,c=k==0?0:b[0].length;if((r==0?0:a[0].length)!=k)throw new IllegalArgumentException();double[][] o=new double[r][c];for(int i=0;i<r;i++)for(int x=0;x<k;x++)if(a[i][x]!=0)for(int j=0;j<c;j++)o[i][j]+=a[i][x]*b[x][j];return o;}public static double[][] transpose(double[][] a){int c=a.length==0?0:a[0].length;double[][] o=new double[c][a.length];for(int i=0;i<a.length;i++)for(int j=0;j<c;j++)o[j][i]=a[i][j];return o;}public static double[][] matrixPower(double[][] a,int e){double[][] r=identity(a.length),b=copy(a);while(e>0){if((e&1)!=0)r=multiply(r,b);b=multiply(b,b);e/=2;}return r;}private static double[][] copy(double[][] a){double[][] o=new double[a.length][];for(int i=0;i<a.length;i++)o[i]=a[i].clone();return o;}public static double determinant(double[][] a){double[][] m=copy(a);double d=1;for(int c=0;c<m.length;c++){int p=c;for(int r=c+1;r<m.length;r++)if(Math.abs(m[r][c])>Math.abs(m[p][c]))p=r;if(Math.abs(m[p][c])<1e-12)return 0;if(p!=c){double[] t=m[p];m[p]=m[c];m[c]=t;d=-d;}d*=m[c][c];for(int r=c+1;r<m.length;r++){double f=m[r][c]/m[c][c];for(int k=c;k<m.length;k++)m[r][k]-=f*m[c][k];}}return d;}public static double[] solveLinearSystem(double[][] a,double[] b){int n=a.length;double[][] m=new double[n][n+1];for(int i=0;i<n;i++){System.arraycopy(a[i],0,m[i],0,n);m[i][n]=b[i];}for(int c=0;c<n;c++){int p=c;for(int r=c+1;r<n;r++)if(Math.abs(m[r][c])>Math.abs(m[p][c]))p=r;if(Math.abs(m[p][c])<1e-12)return null;double[] t=m[p];m[p]=m[c];m[c]=t;for(int r=0;r<n;r++)if(r!=c){double f=m[r][c]/m[c][c];for(int k=c;k<=n;k++)m[r][k]-=f*m[c][k];}}double[] o=new double[n];for(int i=0;i<n;i++)o[i]=m[i][n]/m[i][i];return o;}
}
